<?php require_once 'includes/db.php';require_once 'includes/functions.php';if($_SERVER['REQUEST_METHOD']==='POST'){verify_token();$a=$_POST['action']??'';$id=(int)($_POST['id']??0);if($a==='add'&&$id){$s=$conn->prepare("SELECT stock FROM products WHERE id=? AND active=1");$s->bind_param('i',$id);$s->execute();$p=$s->get_result()->fetch_assoc();if($p&&$p['stock']>0){$qty=max(1,(int)($_POST['qty']??1));$_SESSION['cart'][$id]=min((int)($_SESSION['cart'][$id]??0)+$qty,(int)$p['stock']);flash('Added to your cart.');}else flash('This item is out of stock.');}elseif($a==='update'&&$id){$qty=(int)$_POST['qty'];if($qty<=0)unset($_SESSION['cart'][$id]);else $_SESSION['cart'][$id]=min($qty,99);}elseif($a==='remove')unset($_SESSION['cart'][$id]);header('Location: cart.php');exit;}
$items=[];$total=0;foreach($_SESSION['cart']??[] as $id=>$qty){$id=(int)$id;$s=$conn->prepare("SELECT * FROM products WHERE id=? AND active=1");$s->bind_param('i',$id);$s->execute();$p=$s->get_result()->fetch_assoc();if(!$p||!$p['stock']){unset($_SESSION['cart'][$id]);continue;}$p['qty']=min((int)$qty,(int)$p['stock']);$p['line']=$p['qty']*$p['price'];$total+=$p['line'];$items[]=$p;}$title='Your cart';include 'includes/header.php';?>
<section><div class="heading"><div><small>YOUR SELECTION</small><h2>Your shopping cart</h2></div><a href="index.php">Continue shopping →</a></div><?php if(!$items):?><div class="empty"><h2>Your cart is waiting</h2><p>Add something you love from the collection.</p><a class="btn dark" href="index.php">Browse products</a></div><?php else:?><div class="cart-layout"><div><?php foreach($items as $p):?><div class="cart-item"><img src="<?=e($p['image_url'])?>" onerror="this.src='assets/product.svg'" alt=""><div class="grow"><b><?=e($p['name'])?></b><p>₹<?=number_format($p['price'],2)?></p><div class="actions"><form method="post"><input type="hidden" name="csrf" value="<?=e(token())?>"><input type="hidden" name="action" value="update"><input type="hidden" name="id" value="<?=$p['id']?>"><input type="number" name="qty" min="0" max="<?=$p['stock']?>" value="<?=$p['qty']?>"><button>Update</button></form><form method="post"><input type="hidden" name="csrf" value="<?=e(token())?>"><input type="hidden" name="action" value="remove"><input type="hidden" name="id" value="<?=$p['id']?>"><button class="danger">Remove</button></form></div></div><b>₹<?=number_format($p['line'],2)?></b></div><?php endforeach;?></div><aside class="summary"><h3>Order summary</h3><p>Subtotal <b>₹<?=number_format($total,2)?></b></p><hr><p>Total <b>₹<?=number_format($total,2)?></b></p><a class="btn dark full" href="checkout.php">Proceed to checkout</a><small>Demo project — no real payment collected.</small></aside></div><?php endif;?></section><?php include 'includes/footer.php';?>